{
  "name": "HP 8714ES 射频网络分析仪",
  "name_en": "HP 8714ES RF Network Analyzer",
  "manufacturer": "Hewlett-Packard (HP)",
  "description": "一台台式射频网络分析仪，用于在设定频率范围内进行扫频测量并观察器件的响应迹线。常用于滤波器、谐振器、电缆及其他射频器件的调试与表征，可设置输出功率、扫频参数、带宽，并利用标记和峰值搜索功能分析测量结果。",
  "description_en": "A benchtop RF network analyzer used to sweep frequency and observe response traces of devices under test. It is commonly used to characterize and troubleshoot filters, resonators, cables, and other RF components, with controls for source power, sweep settings, bandwidth, markers, and peak search.",
  "tag_hints": [
    "RF network analysis",
    "frequency sweep measurement",
    "RF component characterization",
    "trace acquisition",
    "marker and peak search",
    "source power control",
    "resolution bandwidth"
  ],
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "复位仪器到默认状态。",
      "description_en": "Reset the instrument to its default state."
    },
    {
      "action_name": "auto-clear_buffers",
      "description": "清空仪器缓冲区。",
      "description_en": "Clear the instrument buffers."
    },
    {
      "action_name": "auto-autoset",
      "description": "自动调整测量显示与扫频设置。",
      "description_en": "Automatically adjust the measurement display and sweep settings."
    },
    {
      "action_name": "auto-powerToggle",
      "description": "获取/设置射频输出开关。",
      "description_en": "Get/set the RF output on/off state."
    },
    {
      "action_name": "auto-powerOutput",
      "description": "获取/设置输出功率电平。",
      "description_en": "Get/set the output power level."
    },
    {
      "action_name": "auto-powerAttenuation",
      "description": "获取/设置输出衰减。",
      "description_en": "Get/set the output attenuation."
    },
    {
      "action_name": "auto-sweepMode",
      "description": "获取/设置扫频模式。",
      "description_en": "Get/set the sweep mode."
    },
    {
      "action_name": "auto-sweepPoints",
      "description": "获取/设置扫频点数。",
      "description_en": "Get/set the number of sweep points."
    },
    {
      "action_name": "auto-frequencyStart",
      "description": "获取/设置起始频率。",
      "description_en": "Get/set the start frequency."
    },
    {
      "action_name": "auto-frequencyStop",
      "description": "获取/设置终止频率。",
      "description_en": "Get/set the stop frequency."
    },
    {
      "action_name": "auto-frequencyCenter",
      "description": "获取/设置中心频率。",
      "description_en": "Get/set the center frequency."
    },
    {
      "action_name": "auto-frequencySpan",
      "description": "获取/设置频率跨度。",
      "description_en": "Get/set the frequency span."
    },
    {
      "action_name": "auto-amplitudeReference",
      "description": "获取/设置幅度参考电平。",
      "description_en": "Get/set the amplitude reference level."
    },
    {
      "action_name": "auto-amplitudeOffset",
      "description": "获取/设置幅度偏移。",
      "description_en": "Get/set the amplitude offset."
    },
    {
      "action_name": "auto-amplitudeScale",
      "description": "获取/设置幅度刻度因子。",
      "description_en": "Get/set the amplitude scale factor."
    },
    {
      "action_name": "auto-markerToggle",
      "description": "打开/关闭指定通道的标记。",
      "description_en": "Enable/disable the marker for the specified channel."
    },
    {
      "action_name": "auto-markerTracking",
      "description": "打开/关闭指定通道的标记跟踪。",
      "description_en": "Enable/disable marker tracking for the specified channel."
    },
    {
      "action_name": "auto-markerFunction",
      "description": "获取/设置标记功能模式。",
      "description_en": "Get/set the marker function mode."
    },
    {
      "action_name": "auto-markerMeasure",
      "description": "读取指定通道的标记测量值。",
      "description_en": "Read the marker measurement value for the specified channel."
    },
    {
      "action_name": "auto-peakSearch",
      "description": "执行峰值搜索。",
      "description_en": "Perform a peak search."
    },
    {
      "action_name": "auto-peakSet",
      "description": "将标记设到峰值位置。",
      "description_en": "Set the marker to a peak position."
    },
    {
      "action_name": "auto-peakNext",
      "description": "跳转到下一个峰值。",
      "description_en": "Move the marker to the next peak."
    },
    {
      "action_name": "auto-bandwidthSweepTime",
      "description": "获取/设置扫频时间。",
      "description_en": "Get/set the sweep time."
    },
    {
      "action_name": "auto-bandwidthResolution",
      "description": "获取/设置分辨率带宽。",
      "description_en": "Get/set the resolution bandwidth."
    },
    {
      "action_name": "auto-traceSetup",
      "description": "配置指定通道的迹线设置。",
      "description_en": "Configure the trace settings for the specified channel."
    },
    {
      "action_name": "auto-traceAcquire",
      "description": "采集指定通道的迹线数据。",
      "description_en": "Acquire trace data for the specified channel."
    }
  ]
}

